      xm
    })

    let f_plus = f(x_plus)
    let f_minus = f(x_minus)

    let grad_i = (f_plus.data[0] - f_minus.data[0]) / (2.0 * h)
    append(acc, grad_i)
  })

  Tensor {
    data: grad,
    shape: x.shape,
    strides: x.strides,
    ndim: x.ndim,
    size: x.size
  }
}

