// ==================================================
// Comprehensive test suite for attention.fl
// Status: 🟢 Testing (20 test cases)

module test_attention

import tensor
import nn
import attention

// ==================================================
// 1. MULTI-HEAD ATTENTION INITIALIZATION TESTS
// ==================================================

function test_mha_init_shapes() -> Bool = {
  let mha = multi_head_attention_init(64, 8, true, 42)
