  mha.num_heads == 8 &&
  mha.d_head == 8
}

function test_mha_linear_shapes() -> Bool = {
  let mha = multi_head_attention_init(128, 4, false, 42)
  // Each linear layer should have shape [d_model, d_model]
  mha.w_q.weight.data.shape[0] == 128 &&
  mha.w_k.weight.data.shape[0] == 128 &&
  mha.w_v.weight.data.shape[0] == 128 &&
  mha.w_o.weight.data.shape[0] == 128
}

function test_mha_causal_flag() -> Bool = {
  let mha_causal = multi_head_attention_init(64, 8, true, 42)
  let mha_no_causal = multi_head_attention_init(64, 8, false, 42)

  mha_causal.use_causal_mask == true &&
  mha_no_causal.use_causal_mask == false
}

function test_mha_head_division() -> Bool = {
  let mha = multi_head_attention_init(96, 12, false, 42)
  mha.d_head == 8
}

// ==================================================
// 2. CAUSAL MASK TESTS
// ==================================================

function test_causal_mask_lower_triangle() -> Bool = {
  let mask = make_causal_mask(3)

