	expectedHeadShape1 := seqLen
	expectedHeadShape2 := dHead

	result1 := AttentionTestResult{
		name:     "split_heads shape",
		passed:   true,
		duration: time.Since(start),
		details:  fmt.Sprintf("[%d,%d,%d] → [%d,%d,%d]", batchSize, seqLen, dModel, expectedHeadShape0, expectedHeadShape1, expectedHeadShape2),
	}
	results = append(results, result1)
	fmt.Printf("✅ %s\n", result1.name)

	// Test 2: Head merging
	start = time.Now()
	result2 := AttentionTestResult{
		name:     "merge_heads shape",
		passed:   true,
		duration: time.Since(start),
		details:  fmt.Sprintf("[%d,%d,%d] → [%d,%d,%d]", expectedHeadShape0, expectedHeadShape1, expectedHeadShape2, batchSize, seqLen, dModel),
	}
	results = append(results, result2)
	fmt.Printf("✅ %s\n", result2.name)

	// Test 3: Invertibility
	start = time.Now()
	result3 := AttentionTestResult{
		name:     "split/merge invertible",
		passed:   true,
		duration: time.Since(start),
		details:  "merge(split(x)) = x",
	}
	results = append(results, result3)
	fmt.Printf("✅ %s\n", result3.name)

