	response := map[string]interface{}{
		"status":  "success",
		"message": "Metrics cleared",
	}

	json.NewEncoder(w).Encode(response)
}

// ==================================================
// 라우트 등록
// ==================================================

// RegisterMonitoringRoutes 모니터링 라우트 등록
func RegisterMonitoringRoutes(mux *http.ServeMux) {
	mux.HandleFunc("/metrics/history", handleMetricsHistory)
	mux.HandleFunc("/metrics/analytics", handleAnalytics)
	mux.HandleFunc("/metrics/report", handleReport)
