	fmt.Println("✅ Monitoring routes registered")
	fmt.Println("   GET    /metrics/history   - Training history")
	fmt.Println("   GET    /metrics/analytics - Analytics")
	fmt.Println("   GET    /metrics/report    - Performance report")
	fmt.Println("   GET    /metrics/health    - System health")
