	}

	if format == "csv" {
		w.Header().Set("Content-Type", "text/csv")
		w.Header().Set("Content-Disposition", "attachment; filename=checkpoints.csv")
		fmt.Fprintf(w, "Name,Epoch,Step,Loss,ValLoss,Timestamp\n")
		fmt.Fprintf(w, "checkpoint_epoch5_step500,5,500,8.9546,8.6297,2026-03-21 10:30:00\n")
		fmt.Fprintf(w, "best_model_valloss8.62,4,400,8.9832,8.6229,2026-03-21 10:25:00\n")
