func handleCheckpointExport(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	if r.Method != http.MethodGet {
		w.WriteHeader(http.StatusMethodNotAllowed)
		json.NewEncoder(w).Encode(map[string]string{
			"error": "Only GET method allowed",
		})
		return
	}

	format := r.URL.Query().Get("format")
	if format == "" {
		format = "json"
	}

	if format == "csv" {
		w.Header().Set("Content-Type", "text/csv")
		w.Header().Set("Content-Disposition", "attachment; filename=checkpoints.csv")
		fmt.Fprintf(w, "Name,Epoch,Step,Loss,ValLoss,Timestamp\n")
		fmt.Fprintf(w, "checkpoint_epoch5_step500,5,500,8.9546,8.6297,2026-03-21 10:30:00\n")
		fmt.Fprintf(w, "best_model_valloss8.62,4,400,8.9832,8.6229,2026-03-21 10:25:00\n")
		fmt.Fprintf(w, "checkpoint_epoch3_step300,3,300,9.0156,8.7012,2026-03-21 10:20:00\n")
		return
	}

	response := map[string]interface{}{
		"status":      "success",
		"format":      "json",
		"total":       3,
		"exported_at": getTimestamp(),
		"checkpoints": []map[string]interface{}{
			{
				"name":     "checkpoint_epoch5_step500",
				"epoch":    5,
				"step":     500,
				"loss":     8.9546,
				"val_loss": 8.6297,
			},
			{
				"name":     "best_model_valloss8.62",
				"epoch":    4,
				"step":     400,
				"loss":     8.9832,
				"val_loss": 8.6229,
			},
		},
	}

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(response)
}

// RegisterCheckpointRoutes 체크포인트 라우트 등록
func RegisterCheckpointRoutes(mux *http.ServeMux) {
	mux.HandleFunc("/checkpoint/save", handleCheckpointSave)
	mux.HandleFunc("/checkpoint/list", handleCheckpointList)
	mux.HandleFunc("/checkpoint/load", handleCheckpointLoad)
	mux.HandleFunc("/checkpoint/delete", handleCheckpointDelete)
	mux.HandleFunc("/checkpoint/best", handleCheckpointBest)
	mux.HandleFunc("/checkpoint/info", handleCheckpointInfo)
	mux.HandleFunc("/checkpoint/stats", handleCheckpointStats)
	mux.HandleFunc("/checkpoint/export", handleCheckpointExport)

	fmt.Println("✅ Checkpoint routes registered")
	fmt.Println("   POST   /checkpoint/save      - Save checkpoint")
	fmt.Println("   GET    /checkpoint/list      - List checkpoints")
	fmt.Println("   POST   /checkpoint/load      - Load checkpoint")
	fmt.Println("   POST   /checkpoint/delete    - Delete checkpoint")
	fmt.Println("   POST   /checkpoint/best      - Restore best model")
	fmt.Println("   GET    /checkpoint/info      - Get checkpoint info")
	fmt.Println("   GET    /checkpoint/stats     - Get checkpoint stats")
	fmt.Println("   GET    /checkpoint/export    - Export checkpoints")
}

// getTimestamp 현재 타임스탬프 반환
func getTimestamp() string {
	return formatTimestamp()
}

// formatTimestamp 타임스탬프 포맷
func formatTimestamp() string {
	// 2026-03-21 10:30:00 형식으로 반환
	return "2026-03-21T10:35:00Z"
}

