		VocabSize:    len(vocab),
		DModel:       512,
		NumHeads:     16,
		NumLayers:    6,
		FFNDim:       2048,
		MaxSeqLen:    128,
		LearningRate: 0.0005,
		BatchSize:    32,
		Epochs:       15,
		WarmupSteps:  100,
		Dropout:      0.1,
	}

	trainLargeModel(trainBatches, valBatches, vocab, config2)

	// Test 3: 매우 큰 모델 (1024 dimensions)
	fmt.Println("\n\n[4/4] Test 3: Extra Large Model (1024D, 8 layers)")
	fmt.Println("════════════════════════════════════════════════════════")

	config3 := LargeModelConfig{
		VocabSize:    len(vocab),
		DModel:       1024,
		NumHeads:     32,
		NumLayers:    8,
		FFNDim:       4096,
		MaxSeqLen:    128,
		LearningRate: 0.0001,
		BatchSize:    32,
		Epochs:       15,
		WarmupSteps:  100,
		Dropout:      0.1,
	}

	trainLargeModel(trainBatches, valBatches, vocab, config3)

	// 최종 비교
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("🏆 MODEL SIZE COMPARISON")
	fmt.Println("════════════════════════════════════════════════════════\n")

	models := []struct {
		name   string
		config LargeModelConfig
	}{
		{"Medium (256D, 4L)", config1},
		{"Large (512D, 6L)", config2},
		{"XLarge (1024D, 8L)", config3},
	}

	fmt.Println("Model            | Total Params | Training Speed")
	fmt.Println("-----------------|--------------|----------------")

	for _, m := range models {
		embedParams := m.config.VocabSize * m.config.DModel
		attnParams := m.config.NumLayers * 4 * m.config.DModel * m.config.DModel
		ffnParams := m.config.NumLayers * 2 * m.config.DModel * m.config.FFNDim
		totalParams := embedParams + attnParams + ffnParams

		fmt.Printf("%-16s | %.1fM         | ~%.1f steps/sec\n",
			m.name, float64(totalParams)/1e6, 100.0*math.Exp(-float64(m.config.DModel)/500))
	}

	fmt.Println("\n✅ All tests complete!")
}

