package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// ==================================================
// 텍스트 생성 API 엔드포인트
// ==================================================

// GenerationRequest 생성 요청
type GenerationRequest struct {
	Prompt      string  `json:"prompt"`
	MaxTokens   int     `json:"max_tokens"`
	Temperature float64 `json:"temperature"`
	TopK        int     `json:"top_k"`
	Method      string  `json:"method"` // "greedy", "sampling", "beam"
}

// GenerationResponse 생성 응답
type GenerationResponse struct {
	Prompt          string   `json:"prompt"`
	Generated       string   `json:"generated"`
	FullText        string   `json:"full_text"`
	Tokens          []int    `json:"tokens"`
	TokenCount      int      `json:"token_count"`
	GeneratedCount  int      `json:"generated_count"`
	Method          string   `json:"method"`
	Temperature     float64  `json:"temperature"`
	Confidence      float64  `json:"confidence"`
	Timestamp       string   `json:"timestamp"`
	ProcessingTime  float64  `json:"processing_time_ms"`
	Status          string   `json:"status"`
}

// BatchGenerationRequest 배치 생성 요청
type BatchGenerationRequest struct {
	Prompts     []string `json:"prompts"`
	MaxTokens   int      `json:"max_tokens"`
	Temperature float64  `json:"temperature"`
	Method      string   `json:"method"`
}

// BatchGenerationResponse 배치 생성 응답
type BatchGenerationResponse struct {
	Generations []GenerationResponse `json:"generations"`
	TotalTime   float64              `json:"total_time_ms"`
	Count       int                  `json:"count"`
	Status      string               `json:"status"`
}

// GenerateText 단일 텍스트 생성 API
func GenerateText(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req GenerationRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	// 기본값 설정
	if req.MaxTokens == 0 {
		req.MaxTokens = 50
	}
	if req.Temperature == 0 {
		req.Temperature = 1.0
	}
	if req.Method == "" {
		req.Method = "greedy"
	}

	// 생성 시뮬레이션
	generatedText := req.Prompt + " [생성된 텍스트]"
	tokens := []int{100, 200, 300, 400, 500} // 시뮬레이션

	confidence := 0.85

	resp := GenerationResponse{
		Prompt:         req.Prompt,
		Generated:      generatedText[len(req.Prompt):],
		FullText:       generatedText,
		Tokens:         tokens,
		TokenCount:     len(tokens),
		GeneratedCount: len(tokens) - len(req.Prompt),
		Method:         req.Method,
		Temperature:    req.Temperature,
		Confidence:     confidence,
		Timestamp:      getCurrentTimestamp(),
		ProcessingTime: 25.3,
		Status:         "success",
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// GenerateTextBatch 배치 텍스트 생성 API
func GenerateTextBatch(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req BatchGenerationRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	if len(req.Prompts) == 0 {
		http.Error(w, "No prompts provided", http.StatusBadRequest)
		return
	}

	// 기본값
	if req.MaxTokens == 0 {
		req.MaxTokens = 50
	}
	if req.Temperature == 0 {
		req.Temperature = 1.0
	}

	generations := make([]GenerationResponse, 0)

	for _, prompt := range req.Prompts {
		generated := prompt + " [생성됨]"
		tokens := []int{100, 200, 300}

		gen := GenerationResponse{
			Prompt:         prompt,
			Generated:      generated[len(prompt):],
			FullText:       generated,
			Tokens:         tokens,
			TokenCount:     len(tokens),
			GeneratedCount: len(tokens),
			Method:         req.Method,
			Temperature:    req.Temperature,
			Confidence:     0.82,
			Timestamp:      getCurrentTimestamp(),
			ProcessingTime: 15.2,
			Status:         "success",
		}

		generations = append(generations, gen)
	}

	resp := BatchGenerationResponse{
		Generations: generations,
		TotalTime:   float64(len(req.Prompts)) * 15.2,
		Count:       len(generations),
		Status:      "success",
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// StreamGenerate 스트리밍 텍스트 생성 API
func StreamGenerate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req GenerationRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/x-ndjson")
	w.Header().Set("Transfer-Encoding", "chunked")

	// 스트리밍 시뮬레이션
	tokens := []string{"[생성중]", "토큰1", "토큰2", "토큰3"}

	for i, token := range tokens {
		event := map[string]interface{}{
			"index":   i,
			"token":   token,
