	Status          string   `json:"status"`
}

// BatchGenerationRequest 배치 생성 요청
type BatchGenerationRequest struct {
	Prompts     []string `json:"prompts"`
	MaxTokens   int      `json:"max_tokens"`
	Temperature float64  `json:"temperature"`
	Method      string   `json:"method"`
}

// BatchGenerationResponse 배치 생성 응답
type BatchGenerationResponse struct {
	Generations []GenerationResponse `json:"generations"`
	TotalTime   float64              `json:"total_time_ms"`
	Count       int                  `json:"count"`
	Status      string               `json:"status"`
}

// GenerateText 단일 텍스트 생성 API
func GenerateText(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req GenerationRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	// 기본값 설정
	if req.MaxTokens == 0 {
		req.MaxTokens = 50
	}
	if req.Temperature == 0 {
		req.Temperature = 1.0
	}
	if req.Method == "" {
		req.Method = "greedy"
	}

	// 생성 시뮬레이션
	generatedText := req.Prompt + " [생성된 텍스트]"
	tokens := []int{100, 200, 300, 400, 500} // 시뮬레이션

	confidence := 0.85

	resp := GenerationResponse{
		Prompt:         req.Prompt,
		Generated:      generatedText[len(req.Prompt):],
		FullText:       generatedText,
		Tokens:         tokens,
		TokenCount:     len(tokens),
		GeneratedCount: len(tokens) - len(req.Prompt),
		Method:         req.Method,
		Temperature:    req.Temperature,
		Confidence:     confidence,
		Timestamp:      getCurrentTimestamp(),
		ProcessingTime: 25.3,
		Status:         "success",
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

// GenerateTextBatch 배치 텍스트 생성 API
func GenerateTextBatch(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req BatchGenerationRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	if len(req.Prompts) == 0 {
		http.Error(w, "No prompts provided", http.StatusBadRequest)
		return
	}

	// 기본값
	if req.MaxTokens == 0 {
		req.MaxTokens = 50
	}
	if req.Temperature == 0 {
		req.Temperature = 1.0
	}

	generations := make([]GenerationResponse, 0)

	for _, prompt := range req.Prompts {
		generated := prompt + " [생성됨]"
		tokens := []int{100, 200, 300}

		gen := GenerationResponse{
