package main

import (
	"fmt"
	"math"
	"math/rand"
)

// ==================================================
// 진짜 Cross-Entropy Loss 구현
// ==================================================

// SimpleModel 간단한 모델 시뮬레이션
type SimpleModel struct {
	vocabSize int
	dModel    int
	embedding [][]float64 // [vocabSize][dModel] 임베딩 테이블
	logits    []float64    // [vocabSize] 로짓 출력층
}

// NewSimpleModel 새로운 모델 생성
func NewSimpleModel(vocabSize, dModel int) *SimpleModel {
	// 임베딩 테이블 초기화 (Xavier)
	embedding := make([][]float64, vocabSize)
	scale := math.Sqrt(2.0 / float64(dModel))
	for i := 0; i < vocabSize; i++ {
		embedding[i] = make([]float64, dModel)
		for j := 0; j < dModel; j++ {
			embedding[i][j] = (rand.Float64() - 0.5) * scale
		}
	}

	logits := make([]float64, vocabSize)

	return &SimpleModel{
		vocabSize: vocabSize,
		dModel:    dModel,
		embedding: embedding,
		logits:    logits,
	}
}

// forward 입력 시퀀스 → 로짓 생성
// 시뮬레이션: 마지막 토큰의 임베딩 → 로짓 투영
func (m *SimpleModel) forward(sequence []int) []float64 {
	if len(sequence) == 0 {
		return m.logits
	}

	// 마지막 토큰의 임베딩
	lastToken := sequence[len(sequence)-1]
	lastEmb := m.embedding[lastToken]

	// 로짓 = 임베딩 @ W (간단한 선형 투영)
	// W는 [dModel, vocabSize] → 모든 vocab에 대한 점수
	for i := 0; i < m.vocabSize; i++ {
		score := 0.0
		for j := 0; j < m.dModel; j++ {
			// 간단함: embedding[i][j] * embedding[lastToken][j]
			score += m.embedding[i][j] * lastEmb[j]
		}
		m.logits[i] = score
	}

	return m.logits
}

// softmax 로짓 → 확률 분포 (수치 안정)
func softmax(logits []float64) []float64 {
	// max 감산으로 오버플로우 방지
	maxLogit := logits[0]
	for _, l := range logits {
		if l > maxLogit {
			maxLogit = l
		}
	}

	// exp 계산
	sumExp := 0.0
	probs := make([]float64, len(logits))
	for i, l := range logits {
		probs[i] = math.Exp(l - maxLogit)
		sumExp += probs[i]
	}

	// 정규화
	for i := range probs {
		probs[i] /= sumExp
	}

	return probs
}

// crossEntropyLoss 진짜 Cross-Entropy 손실
// loss = -log(P(correct_token))
func crossEntropyLoss(probs []float64, correctToken int) float64 {
	if correctToken < 0 || correctToken >= len(probs) {
		return 0.0
	}

	prob := probs[correctToken]
	if prob <= 0 {
		prob = 1e-10 // 수치 안정성
	}

	return -math.Log(prob)
}

// trainWithRealLoss 진짜 Cross-Entropy 손실로 학습
func trainWithRealLoss() {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  Real Loss Training - 진짜 Cross-Entropy 손실로 학습   ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	// 데이터 로드
	fmt.Println("[1/4] Loading tokenized data...")
	tokens, vocab, err := tokenizeRealData("train/data/real_corpus_large.txt")
	if err != nil {
		fmt.Printf("❌ Error: %v\n", err)
		return
	}

	fmt.Printf("✅ Loaded %d tokens from %d vocab\n\n", len(tokens), len(vocab))

	// 모델 생성
	fmt.Println("[2/4] Creating model...")
	model := NewSimpleModel(len(vocab), 64) // 작은 모델: 64D
	fmt.Printf("✅ Model created: vocab=%d, dModel=64\n\n", len(vocab))

	// 학습 설정
	fmt.Println("[3/4] Training setup...")
	sequenceLen := 32
	batchSize := 64
	epochs := 5
	learningRate := 0.001

	numBatches := (len(tokens) - sequenceLen) / batchSize
	if numBatches > 500 { // 시간 제한
		numBatches = 500
	}

	fmt.Printf("   Sequence length: %d\n", sequenceLen)
	fmt.Printf("   Batch size: %d\n", batchSize)
	fmt.Printf("   Batches per epoch: %d\n", numBatches)
	fmt.Printf("   Learning rate: %.6f\n\n", learningRate)

	// 학습 루프
	fmt.Println("[4/4] Training...")
	fmt.Println("════════════════════════════════════════════════════════")

	losses := make([]float64, 0)

	for epoch := 1; epoch <= epochs; epoch++ {
		epochLoss := 0.0
		batchCount := 0

		for batch := 0; batch < numBatches; batch++ {
			// 랜덤 위치에서 시퀀스 샘플
			startIdx := rand.Intn(len(tokens) - sequenceLen - 1)
			seq := tokens[startIdx : startIdx+sequenceLen]
			targetToken := tokens[startIdx+sequenceLen]

			// Forward pass: 로짓 생성
			logits := model.forward(seq)

			// Softmax: 확률 분포 계산
			probs := softmax(logits)

			// Loss: Cross-Entropy = -log(P(correct_token))
			loss := crossEntropyLoss(probs, targetToken)
			epochLoss += loss

			// 실제 그래디언트 기반 업데이트
			// dL/dlogit[i] = probs[i] - (1 if i==targetToken else 0)
			// 간단화: 정확한 토큰 임베딩은 올리고, 다른 것들은 낮춘다
			if targetToken < len(model.embedding) {
				// 정확한 토큰 임베딩: 손실 감소 방향으로 이동
				for j := 0; j < model.dModel; j++ {
					gradient := -model.embedding[targetToken][j] * (1.0 - probs[targetToken])
					model.embedding[targetToken][j] -= learningRate * gradient
				}
			}

			batchCount++

			// 진행 상황 출력
			if batch%50 == 0 {
				avgLoss := epochLoss / float64(batchCount)
				ppl := math.Exp(avgLoss)
				fmt.Printf("Epoch %d, Batch %d/%d: Loss=%.4f, PPL=%.2f\r",
					epoch, batch+1, numBatches, avgLoss, ppl)
			}
		}

		if batchCount > 0 {
			avgEpochLoss := epochLoss / float64(batchCount)
			ppl := math.Exp(avgEpochLoss)
			losses = append(losses, avgEpochLoss)

			fmt.Printf("\n✅ Epoch %d: Loss=%.4f, PPL=%.2f\n", epoch, avgEpochLoss, ppl)
		}
	}

	// 결과 분석
	fmt.Println("\n════════════════════════════════════════════════════════")
	fmt.Println("🎯 Training Complete!")
	fmt.Println("════════════════════════════════════════════════════════\n")

	fmt.Println("📊 Loss Trajectory:")
	for i, loss := range losses {
		ppl := math.Exp(loss)
		bar := ""
		barLen := int(loss * 1.5)
		if barLen > 50 {
			barLen = 50
		}
		for j := 0; j < barLen; j++ {
			bar += "█"
		}
		fmt.Printf("  Epoch %d: %s %.4f (PPL: %.2f)\n", i+1, bar, loss, ppl)
