package main

import (
	"fmt"
	"math"
)

// ==================================================
// Adam Optimizer Implementation (Go 포팅)
// Source: src/optimizer.fl (Priority 3)
// ==================================================

// AdamState 아담 옵티마이저 상태
type AdamState struct {
	LearningRate float64   // learning rate
	Beta1        float64   // 0.9 (1st moment decay)
	Beta2        float64   // 0.999 (2nd moment decay)
	Eps          float64   // 1e-8 (numerical stability)
	T            int       // timestep
	M            []float64 // 1st moment (momentum)
	V            []float64 // 2nd moment (variance)
}

// SGDState SGD 옵티마이저 상태
type SGDState struct {
	LearningRate float64
	Momentum     float64
	Velocity     []float64
}

// MomentumState Momentum 옵티마이저 상태
type MomentumState struct {
	LearningRate float64
	Beta         float64   // 0.9
	Velocity     []float64 // v_t = beta * v_{t-1} + grad
}

// ==================================================
// Initialize Optimizers
// ==================================================

// NewAdamState Adam 옵티마이저 초기화
func NewAdamState(learningRate float64, paramSize int) *AdamState {
	return &AdamState{
		LearningRate: learningRate,
		Beta1:        0.9,
		Beta2:        0.999,
		Eps:          1e-8,
		T:            0,
		M:            make([]float64, paramSize),
		V:            make([]float64, paramSize),
	}
}

// NewSGDState SGD 옵티마이저 초기화
func NewSGDState(learningRate float64, paramSize int) *SGDState {
	return &SGDState{
		LearningRate: learningRate,
		Momentum:     0.0,
		Velocity:     make([]float64, paramSize),
	}
}

// NewMomentumState Momentum 옵티마이저 초기화
func NewMomentumState(learningRate float64, beta float64, paramSize int) *MomentumState {
	return &MomentumState{
		LearningRate: learningRate,
		Beta:         beta,
		Velocity:     make([]float64, paramSize),
	}
}

// ==================================================
// Adam Step (핵심)
// ==================================================

// AdamStep Adam 한 스텝 업데이트
// 수식:
//   m_t = beta1 * m_{t-1} + (1 - beta1) * g_t
//   v_t = beta2 * v_{t-1} + (1 - beta2) * g_t^2
//   m_hat = m_t / (1 - beta1^t)
//   v_hat = v_t / (1 - beta2^t)
//   w -= lr * m_hat / (sqrt(v_hat) + eps)
func (s *AdamState) Step(params []float64, grads []float64) []float64 {
	if len(params) != len(grads) || len(params) != len(s.M) || len(params) != len(s.V) {
		fmt.Printf("❌ AdamState size mismatch: params=%d, grads=%d, m=%d, v=%d\n",
			len(params), len(grads), len(s.M), len(s.V))
		return params
	}

	// Step 1: t += 1
	s.T++
	tFloat := float64(s.T)

	// Step 2: m_t = beta1 * m_{t-1} + (1 - beta1) * g_t
	for i := range grads {
		s.M[i] = s.Beta1*s.M[i] + (1.0-s.Beta1)*grads[i]
	}

	// Step 3: v_t = beta2 * v_{t-1} + (1 - beta2) * g_t^2
	for i := range grads {
		s.V[i] = s.Beta2*s.V[i] + (1.0-s.Beta2)*(grads[i]*grads[i])
	}

	// Step 4: Bias correction
	bias_corr1 := 1.0 - math.Pow(s.Beta1, tFloat)
	bias_corr2 := 1.0 - math.Pow(s.Beta2, tFloat)

	// Step 5-6: w -= lr * m_hat / (sqrt(v_hat) + eps)
	updated := make([]float64, len(params))
	for i := range params {
		m_hat := s.M[i] / bias_corr1
		v_hat := s.V[i] / bias_corr2
		denom := math.Sqrt(v_hat) + s.Eps
		updated[i] = params[i] - s.LearningRate*m_hat/denom
	}

	return updated
}

// ==================================================
// SGD Step
// ==================================================

// SGDStep SGD 한 스텝 업데이트
// 수식: w -= lr * grad
func (s *SGDState) Step(params []float64, grads []float64) []float64 {
	if len(params) != len(grads) {
		fmt.Printf("❌ SGDState size mismatch: params=%d, grads=%d\n", len(params), len(grads))
		return params
	}

	updated := make([]float64, len(params))
	for i := range params {
		updated[i] = params[i] - s.LearningRate*grads[i]
	}
	return updated
}

// ==================================================
// Momentum Step
// ==================================================

// MomentumStep Momentum 한 스텝 업데이트
// 수식: v_t = beta * v_{t-1} + grad, w -= lr * v_t
func (s *MomentumState) Step(params []float64, grads []float64) []float64 {
	if len(params) != len(grads) || len(params) != len(s.Velocity) {
		fmt.Printf("❌ MomentumState size mismatch: params=%d, grads=%d, vel=%d\n",
			len(params), len(grads), len(s.Velocity))
		return params
	}

	// v_t = beta * v_{t-1} + grad
	for i := range grads {
		s.Velocity[i] = s.Beta*s.Velocity[i] + grads[i]
	}

	// w -= lr * v_t
	updated := make([]float64, len(params))
	for i := range params {
		updated[i] = params[i] - s.LearningRate*s.Velocity[i]
	}
	return updated
}

// ==================================================
// Utility Functions
// ==================================================

// ClipGradient 그래디언트 클리핑 (최대 norm 제한)
func ClipGradient(grads []float64, maxNorm float64) []float64 {
	// norm = sqrt(sum(g^2))
	norm := 0.0
	for _, g := range grads {
		norm += g * g
	}
	norm = math.Sqrt(norm)

	if norm <= 0 {
		return grads
	}

	if norm > maxNorm {
		// scale by maxNorm / norm
		scale := maxNorm / norm
		clipped := make([]float64, len(grads))
		for i, g := range grads {
			clipped[i] = g * scale
		}
		return clipped
	}

	return grads
}

// LRScheduleLinear 선형 감소 학습률
func LRScheduleLinear(initialLR float64, epoch int, totalEpochs int) float64 {
	return initialLR * (1.0 - float64(epoch)/float64(totalEpochs))
}

// LRScheduleExponential 지수 감소 학습률
func LRScheduleExponential(initialLR float64, epoch int, decayRate float64) float64 {
	return initialLR * math.Pow(decayRate, float64(epoch))
}

// ==================================================
// Test Functions (검증용)
// ==================================================

// TestOptimizers 옵티마이저 기본 동작 확인
func TestOptimizers() {
	fmt.Println("\n╔════════════════════════════════════════════════════════╗")
	fmt.Println("║  Optimizer Test Suite (Adam, SGD, Momentum)            ║")
	fmt.Println("╚════════════════════════════════════════════════════════╝\n")

	params := []float64{1.0, 2.0, 3.0}
	grads := []float64{0.1, 0.2, 0.3}

	// Test 1: SGD
	fmt.Println("[1/3] Testing SGD...")
	sgd := NewSGDState(0.01, len(params))
	sgdParams := sgd.Step(params, grads)
	fmt.Printf("✅ SGD: params = %v\n", sgdParams)

	// Test 2: Momentum
	fmt.Println("[2/3] Testing Momentum...")
	mom := NewMomentumState(0.01, 0.9, len(params))
	momParams := mom.Step(params, grads)
	fmt.Printf("✅ Momentum: params = %v\n", momParams)

	// Test 3: Adam
	fmt.Println("[3/3] Testing Adam...")
	adam := NewAdamState(0.001, len(params))
	adamParams := adam.Step(params, grads)
	fmt.Printf("✅ Adam (step 1): params = %v\n", adamParams)

	// Test 4: Gradient Clipping
	fmt.Println("\n[4/4] Testing Gradient Clipping...")
	largeGrads := []float64{10.0, 20.0, 30.0}
	clipped := ClipGradient(largeGrads, 5.0)
	fmt.Printf("✅ Clipped grads: %v\n", clipped)

	// Test 5: Learning Rate Schedule
	fmt.Println("\n[5/5] Testing LR Schedules...")
	for epoch := 0; epoch <= 5; epoch++ {
		lr_linear := LRScheduleLinear(0.001, epoch, 5)
		lr_exp := LRScheduleExponential(0.001, epoch, 0.95)
		fmt.Printf("  Epoch %d: Linear=%.6f, Exp=%.6f\n", epoch, lr_linear, lr_exp)
	}

	fmt.Println("\n✅ All optimizer tests passed!")
}

