	fmt.Printf("M size: %d, V size: %d (expected: 3, 3)\n\n", len(adam.M), len(adam.V))

	// Test 2: Adam Step 계산
	fmt.Println("[TEST 2] Adam Step Calculation (Single Step)")
	fmt.Println("════════════════════════════════════════════════════════")
	params := []float64{1.0, 2.0, 3.0}
	grads := []float64{0.1, 0.2, 0.3}

	fmt.Printf("Initial params: %v\n", params)
	fmt.Printf("Gradients: %v\n\n", grads)

	updated := adam.Step(params, grads)
	fmt.Printf("After Adam step 1:\n")
	fmt.Printf("  Updated params: [%.6f, %.6f, %.6f]\n", updated[0], updated[1], updated[2])
	fmt.Printf("  T (timestep): %d\n", adam.T)
	fmt.Printf("  M (1st moment): [%.6f, %.6f, %.6f]\n", adam.M[0], adam.M[1], adam.M[2])
	fmt.Printf("  V (2nd moment): [%.6f, %.6f, %.6f]\n\n", adam.V[0], adam.V[1], adam.V[2])

	// Test 3: 여러 스텝 실행
	fmt.Println("[TEST 3] Multi-Step Convergence")
	fmt.Println("════════════════════════════════════════════════════════")
	adam2 := NewAdamState(0.01, 1) // 1D 테스트
	param := []float64{5.0}
	loss := func(p float64) float64 {
		return (p - 2.0) * (p - 2.0) // 최소값: p=2
