		return 2.0 * (p - 2.0) // 미분: 2(p-2)
	}

	fmt.Printf("Target: minimize (p - 2)^2, optimal p = 2.0\n\n")
	fmt.Printf("Step | Param   | Loss    | Grad   | GradNorm\n")
